const hour = new Date().getUTCHours();
const slot = hour < 12 ? 'am' : 'pm';
return [{ json: { slot, trigger: 'scheduled' } }];

// Sources come from the registry via /api/ingest/sources, not a list
// held in this node. Adding, pausing or purging a source in the app is
// enough - a hardcoded list drifted and left the sweep fetching two
// deleted sources while eleven new ones were never read at all.
const res = $input.first().json;
const sources = Array.isArray(res.sources) ? res.sources : [];
if (!sources.length) {
  throw new Error('Source registry returned no rss sources');
}
const open = $('Open sweep').first().json;
return sources.map((s) => ({
  json: {
    code: s.code,
    feed_url: s.feed_url,
    name: s.name,
    layer: s.layer,
    sweep_id: open.sweep_id,
    sweep_code: open.sweep_code,
  },
}));

// Map each RSS item into the IngestItem envelope. Trim long bodies;
// the route caps them too but it's cheaper to do it here.
// first(), not item(): Loop sources emits exactly one source per
// iteration, and 'Map RSS -> items' drops any entry with a blank
// headline, which breaks n8n's paired-item lineage. Asking for .item
// then fails with "Paired item data ... is unavailable" and takes the
// whole sweep down with it.
const source = $('Loop sources').first().json;
const now = new Date().toISOString();
const items = $input.all().slice(0, 50); // soft cap per source per sweep
return items.map((it) => {
  const r = it.json;
  const headline = (r.title || '').toString().trim();
  if (!headline) return null;
  return {
    json: {
      sweep_id: source.sweep_id,
      source_code: source.code,
      kind: 'rss',
      fetched_at: now,
      item: {
        headline,
        external_id: r.guid || r.id || r.link || null,
        primary_url: r.link || null,
        published_at: r.isoDate || r.pubDate || null,
        summary: r.contentSnippet || r.summary || null,
        body_text: r['content:encoded'] || r.content || null,
        author: r.creator || r['dc:creator'] || r.author || null,
        tags: Array.isArray(r.categories) ? r.categories.slice(0, 16) : [],
        raw: r
      }
    }
  };
}).filter(Boolean);

// Roll the per-source outcome up for /complete. The route ignores
// candidate_count — it counts authoritative rows — but parse_issue_count
// and outcome are honoured.
// first(), not item(): Loop sources emits exactly one source per
// iteration, and 'Map RSS -> items' drops any entry with a blank
// headline, which breaks n8n's paired-item lineage. Asking for .item
// then fails with "Paired item data ... is unavailable" and takes the
// whole sweep down with it.
const source = $('Loop sources').first().json;
return [{
  json: {
    source_code: source.code,
    outcome: 'reached_items',
    http_status: 200,
    parse_issue_count: 0
  }
}];

// RSS fetch failed — record outcome and raise a P2 alert.
// first(), not item(): Loop sources emits exactly one source per
// iteration, and 'Map RSS -> items' drops any entry with a blank
// headline, which breaks n8n's paired-item lineage. Asking for .item
// then fails with "Paired item data ... is unavailable" and takes the
// whole sweep down with it.
const source = $('Loop sources').first().json;
return [{
  json: {
    source_code: source.code,
    outcome: 'parse_failure',
    http_status: 0,
    parse_issue_count: 1,
    _alert: {
      source_code: source.code,
      sweep_id: source.sweep_id,
      severity: 'p2',
      issue_type: 'unreachable',
      description: 'RSS fetch failed for ' + source.code + ' (' + source.feed_url + ')'
    }
  }
}];

// One article would not post. Record it and carry on: losing a
// sweep because a single item was rejected costs every source
// after it, which is what used to happen.
// first(), not item(): Loop sources emits exactly one source per
// iteration, and 'Map RSS -> items' drops any entry with a blank
// headline, which breaks n8n's paired-item lineage. Asking for .item
// then fails with "Paired item data ... is unavailable" and takes the
// whole sweep down with it.
const source = $('Loop sources').first().json;
return [{
  json: {
    source_code: source.code,
    outcome: 'item_failure',
    http_status: $json.error?.httpCode ?? 0,
    parse_issue_count: 1,
    _alert: {
      source_code: source.code,
      sweep_id: source.sweep_id,
      severity: 'p3',
      issue_type: 'item_rejected',
      description: 'Item POST failed for ' + source.code + ': ' + ($json.error?.message ?? 'unknown')
    }
  }
}];
